# Generated by manage.py generate_test_cases.
from django.http import HttpResponse

from bloomerp.models.automation.workflow import Workflow
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestSaveWorkflowView(BloomerpAPIViewTestCase):
    """Tests class `SaveWorkflowView` from `bloomerp/views/api/workflows/save.py`."""

    view_name = 'workflows_save'

    def setUp(self) -> None:
        """Create an existing workflow for update and access-denial scenarios."""
        super().setUp()
        self.workflow = Workflow.objects.create(name="Before save")

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover create/update, graph validation, authentication, and object permissions."""
        payload = {
            "name": "Saved through SDK",
            "nodes": [
                {"client_id": "client-1", "type": "TRIGGER", "sub_type": "HUMAN_TRIGGER", "parameters": {}},
                {"client_id": "client-2", "type": "ACTION", "sub_type": "SEND_EMAIL", "parameters": {}},
            ],
            "edges": [{"from_node": "client-1", "to_node": "client-2"}],
        }
        updated = {**payload, "workflow_id": self.workflow.pk}
        return [
            RequestScenario(
                name="Create a workflow with retained client IDs and output ports",
                method="POST", user=self.admin_user, data=payload, content_type="application/json",
                expected=ExpectedResult(status_code=201, response_validators=self.saved_graph),
            ),
            RequestScenario(
                name="Update an existing workflow graph",
                method="POST", user=self.admin_user, data=updated, content_type="application/json",
                expected=ExpectedResult(response_validators=[
                    self.saved_graph, self.json_key_equals("workflow_id", self.workflow.pk),
                ]),
            ),
            *[
                RequestScenario(
                    name=f"Reject {label}", method="POST", user=self.admin_user,
                    data=invalid, content_type="application/json", expected=ExpectedResult(status_code=status),
                )
                for label, invalid, status in (
                    ("malformed JSON", "{", 400),
                    ("non-object input", [], 400),
                    ("invalid workflow ID", {**payload, "workflow_id": "bad"}, 400),
                    ("zero workflow ID", {**payload, "workflow_id": 0}, 400),
                    ("missing workflow", {**payload, "workflow_id": 999999999}, 404),
                    ("invalid edge", {**updated, "edges": [{"from_node": "missing", "to_node": "client-2"}]}, 400),
                )
            ],
            *[
                RequestScenario(
                    name=f"Deny {label}", method="POST", user=user,
                    data=data, content_type="application/json", expected=ExpectedResult(status_code=status),
                )
                for label, user, data, status in (
                    ("anonymous save", None, payload, 401),
                    ("creation without add permission", self.normal_user, payload, 403),
                    ("update without object permission", self.normal_user, updated, 403),
                )
            ],
            RequestScenario(name="Reject GET", user=self.admin_user, expected=ExpectedResult(status_code=405)),
        ]

    def saved_graph(self, response: HttpResponse) -> bool:
        """Confirm persisted graph identity and the response used to refresh the editor."""
        data = response.json()
        workflow = Workflow.objects.get(pk=data["workflow_id"])
        return (
            workflow.name == "Saved through SDK"
            and workflow.nodes.count() == 2
            and {node["client_id"] for node in data["nodes"]} == {"client-1", "client-2"}
            and all("output_ports" in node for node in data["nodes"])
            and data["edges"][0]["from_node"] == "client-1"
            and data["edges"][0]["to_node"] == "client-2"
        )
